/** Draw one of ART.big at (x, y), its top left: opts { fx, fy (flip the whole sprite), prio (default 3), pal (every
 * part in this sprite palette, e.g. a hit flash) }. Each part is one spr() (generated by art.py). */
function bigSprite(b, x, y, opts = {}) {
  const fx = !!opts.fx, fy = !!opts.fy, prio = opts.prio ?? 3;
  for (const [dx, dy, t, size, pal, f] of b.parts) {
    spr(t, x + (fx ? b.w - dx - size : dx), y + (fy ? b.h - dy - size : dy),
      { size, pal: opts.pal ?? pal, fx: fx !== !!(f & 1), fy: fy !== !!(f & 2), prio });
  }
}
/** In scanline(y): set the CGRAM entry of a gradient from ART.gradients to its colour for line y (generated by art.py). */
function gradientLine(g, y) {
  const v = g.lines[y - g.y0];
  if (v !== undefined) color(g.entry, v & 31, (v >> 5) & 31, v >> 10);
}
/** Draw frame k of a streamed animation from ART.streams at (x, y), its top left: its tiles are copied into the
 * animation's slot first (only those that changed since the slot's last frame). opts { fx, prio (default 3), pal,
 * slot (0 to slots - 1: one for each copy on screen at once) } (generated by art.py). */
function streamSprite(st, k, x, y, opts = {}) {
  const A = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz+/', d = (s, i, n = 1) => {
    let v = 0;
    for (let j = 0; j < n; j++) v = v * 64 + A.indexOf(s[i + j]);
    return v;
  };
  if (!st.px) {                                    // unpack the tiles and the frames, once
    st.px = [new Uint8Array(64)]; st.loaded = []; st.f = [];
    let cur = new Uint8Array(64), n = 0;
    for (let i = 0; i < st.pool.length; i++) {
      const s = A.indexOf(st.pool[i]);
      const r = s < 16 ? s + 1 : (s - 16) % 3 + 1, v = s < 16 ? -1 : ((s - 16) / 3) | 0;
      for (let q = 0; q < r; q++, n++) cur[n] = v >= 0 ? v : n >= 8 ? cur[n - 8] : 0;
      if (n === 64) { st.px.push(cur); cur = new Uint8Array(64); n = 0; }
    }
    for (const s of st.frames) {
      const np = d(s, 0, 2), parts = [];
      for (let p = 0; p < np; p++) {
        const i = 2 + p * 6;
        parts.push([d(s, i) * 8, d(s, i + 1) * 8, d(s, i + 2, 2), 8 << d(s, i + 4), d(s, i + 5)]);
      }
      const ix = [];
      for (let i = 2 + np * 6; i < s.length; i += 2) ix.push(d(s, i, 2));
      st.f.push({ parts, ix });
    }
  }
  const slot = opts.slot ?? 0, base = st.base + slot * st.rows * 16;
  const have = st.loaded[slot] || (st.loaded[slot] = new Int32Array(st.rows * 16).fill(-1));
  const f = st.f[k], fx = !!opts.fx, prio = opts.prio ?? 3;
  let c = 0;
  for (const [dx, dy, off, size, pal] of f.parts) {
    const n = size >> 3;
    for (let j = 0; j < n; j++) for (let i = 0; i < n; i++, c++) {
      const ix = f.ix[c], o = off + j * 16 + i;
      if (have[o] === ix) continue;
      have[o] = ix;
      const t = base + o, tx = (t & 15) * 8, ty = (t >> 4) * 8, p = st.px[ix];
      for (let q = 0; q < 64; q++) sset(tx + (q & 7), ty + (q >> 3), p[q]);
    }
    spr(base + off, x + (fx ? st.w - dx - size : dx), y + dy, { size, pal: opts.pal ?? pal, fx, prio });
  }
}
// END ART

const FEET = 102;           // the figure's canvas: the soles are this many pixels below its top (its margin + height)
const GROUND = 204;         // where his feet are on the screen
const SPEED = { idle: 30, walk: 7, punch: 5, kick: 6 };   // frames each animation frame is shown
let x = 100, facing = 1, act = 'idle', frame = 0, timer = 0;

function init() {
  bg(2, { mx: ART.scenes.city.mx, my: 0, mw: 32, mh: 28, x: 0, y: 12, wrap: true, show: true });
  bg(1, { mx: ART.scenes.fence.mx, my: 0, mw: 32, mh: 28, x: 0, y: 0, wrap: true, show: true });
  bg(0, { mx: ART.scenes.ground.mx, my: 0, mw: 32, mh: 28, x: 0, y: 0, wrap: true, show: true });
}

function start(a) { if (act !== a) { act = a; frame = 0; timer = 0; } }

function update() {
  const busy = (act === 'punch' || act === 'kick');
  if (!busy) {
    if (btnp(A)) start('punch');
    else if (btnp(B)) start('kick');
    else if (btn(LEFT) || btn(RIGHT)) {
      facing = btn(LEFT) ? -1 : 1;
      x = clamp(x + facing * 1.2, -30, 170);
      start('walk');
    } else start('idle');
  }
  const n = ART.streams.hero.clips[act][1];
  if (++timer >= SPEED[act]) {
    timer = 0;
    frame++;
    if (frame >= n) { frame = 0; if (busy) start('idle'); }
  }
}

function draw() {
  cls();
  // his shadow (sprite palette 4) is subtracted from the pavement under him
  blend({ layers: ['spr'], op: 'sub' });
  const st = ART.streams.hero;
  streamSprite(st, st.clips[act][0] + frame, flr(x), GROUND - FEET, { fx: facing < 0, prio: 2 });
  bigSprite(ART.big.shadow, flr(x) + (facing < 0 ? st.w - 44 - 56 : 44) - 4, GROUND - 5, { prio: 2 });
  print('WALK  A:PUNCH  B:KICK', 128 - 21 * 4, 214, ART.colors.WHITE);
}

function scanline(y) { gradientLine(ART.gradients.sky, y); }
